"""Operation details are retrieved on demand instead of bloating MCP schemas."""


def operation_help(component: str = "analysis") -> dict:
    if component == "runtime":
        return {
            "setup": "backend action=install component=runtime returns a job id; poll job status",
            "runtime_actions": {
                "processes": {"limit": "1..200"},
                "spawn": {"exe": "absolute owned executable", "sha256": "required full SHA-256 of exe", "argv": "optional argument array",
                          "cwd": "optional absolute working directory (games resolve data relative to it)",
                          "env": "optional {name: value} added to the caller's environment"},
                "attach": {"pid": "explicit process id", "exe": "expected executable path", "sha256": "required full SHA-256 of exe"},
                "status": {"session": "returned session id", "after": "event cursor", "limit": "bounded event count"},
                "modules": {"session": "id", "limit": "bounded rows"},
                "threads": {"session": "id", "limit": "bounded rows"},
                "read": {"session": "id", "module": "exact loaded module name with rva, OR address for absolute heap/stack", "rva": "module-relative hex offset", "address": "absolute readable target address; mutually exclusive with module/rva", "size": "1..4096 bytes",
                         "layout": "optional [{name, offset, type, size?}]: decode the read as fields", "type": "optional type name from target's analysis (imported/overlay types) as the layout", "target": "the analysis target that defines type"},
                "observe/break": {"session": "id", "module": "exact loaded module", "rva": "offset", "sha256": "module file build hash", "expect": "exact live bytes before installing a probe", "limit": "event count",
                                  "accept_patch": "true: expect is the file's original prologue; a live detour another tool wrote is decoded, reported (patcher module) and probed past",
                                  "instruction": "true for a probe inside a function (no return hook; [sp] is not a return address there); automatic on x64 off a pdata function start",
                                  "convention": "native (default; x64 registers then stack, ia32 stack slots) | thiscall (32-bit: arg 0 = this in ecx) | fastcall (32-bit: ecx, edx, then stack)",
                                  "capture": "up to 4 [{arg 0..7 under the convention, or reg (a register name; x64 xmm0..xmm15 hold float arguments: {reg: xmm2, as: f32}), deref?: [offsets: read a pointer at each], size?, as: utf8|utf16|hex|i8..u64|f32|f64|pointer|struct, fields? (struct), names? {value: name}, label?}]: bounded, range-checked copies decoded in the worker (events carry decoded)",
                                  "sample": "observe only: {window_s 1..300, capture: index of a numeric capture}: one summary per window (count, rate, min, max, last) instead of an event per call"},
                "writers": {"session": "id", "target": "analysis target (checks every site before probing)", "rows": "1..32 sites from ghidra_query action=writes",
                            "object": "the live object's address", "offset": "the field's offset", "size": "1..64", "window_s": "1..60",
                            "answer": "which sites wrote object+offset in the window; a site too short for a probe is counted at its function's return sites; sites a jump lands in, or whose bytes hold a call, are refused with the reason"},
                "patches": {"session": "id", "rows": "[{module, rva, size?, name?}] 1..200: live vs file bytes, decoded detour and its module", "sha256": "module file build hash"},
                "continue": {"session": "id", "hook_id": "optional breakpoint id"},
                "unload": {"session": "id", "hook_id": "probe id"},
                "resume/detach": {"session": "id"},
            },
            "semantics": "Breakpoints capture observed registers, arguments and stack context; bounded automatic release prevents abandoned pauses. Detach removes instrumentation. CPU single-step is not supplied by this instrumentation backend.",
            "trust": "Every built-in probe requires module build identity and matching live bytes. Unrestricted injected scripts are not exposed because they could bypass that gate. No remote target or other MCP server is implied.",
        }
    return {
        "setup": "backend inspect discovers the pinned Hydra Engine, its client and a JDK; backend install starts a private, verified installation job; backend status/stop show or stop the shared engine",
        "prepare": "action=adopt path=<.gpr, its folder or a parent> exe|sha256 [program] [target]: register an analysed project in place (no copy, no import). action=plan exe: read-only preflight. action=start exe [install=true]: one-time import/analysis job; identical builds reuse one result",
        "jobs": "job status with id returns stage, elapsed time and bounded progress log; job cancel requests owned-process cleanup",
        "queries": "ghidra_query uses configured or prepared target, numeric VA or rva:/va:, action, limit/cursor/contains/timeout_s and options. Imported address maps also permit name:<name> and hash:0x<hex>. options.view selects a named annotation view; shared is the default. Views isolate edits, not access control.",
        "prologue": "Single address/expect or checks[{address,expect,name?}], 1..200 rows, one PE open/hash. CLI --checks-file accepts canonical rows or legacy offset/prologue/names with explicit --offset-kind.",
        "actions": {
            "decompile/function/functions/xrefs": "read-only analysed results with bounded continuation",
            "address_map": {"path": "options.path: absolute path to JSON {sha256, source, entries:[{name?, hash?, rva, source?}]}; maps are build-bound and conflicting RVAs are refused"},
            "types": "paged types, optional contains and cursor",
            "type": {"path": "exact database category path, or use address for typed data"},
            "data": {"table": "optional bool: bounded pointer candidates at address; inferred vtables require further evidence"},
            "scan": {"end": "optional inclusive numeric VA", "mnemonic": "literal substring", "operand": "literal substring", "regex": "optional case-insensitive regex over MNEMONIC operands; decoded listing, at most 2000 instructions/page; use next_cursor"},
            "variables": "recovered local/parameter types for address's function",
            "dossier": "bounded function picture with references/callers/callees",
            "blocks": "basic blocks and their observed static edges",
            "pcode": {"nodes": "1..200; stable op/varnode IDs seed a trace"},
            "trace": {"seed": "op/varnode id from pcode", "direction": "backward or forward", "depth": "1..32", "nodes": "1..200", "functions": "1..8"},
            "type_edit": {
                "kind": "struct/signature/variable/apply/rename/label/comment/function_create/function_body/function_delete/batch/import_types/import_archive/revert",
                "shape": "all options are flat, next to kind: {\"kind\": \"struct\", \"path\": ..., \"size\": ..., \"fields\": [...]}, never {\"struct\": {...}}",
                "source": "required supporting evidence", "expect_revision": "REQUIRED for every edit and revert, on the shared view and on named views: the view_revision you read (ghidra_query status, or any edit answer). A missing value is an error that names the current revision. A stale one is rebased automatically (answer rebased:true, rebased_from, subjects_changed_since) when no edit after it touched this edit's subject (address, struct path, or function structure); otherwise it is a conflict {conflict, current_revision, latest_editor {by, at}, subjects_changed_since, overlapping, history_complete}. A type import touches every subject. Subjects are addresses and type paths; dependencies between them are not tracked. A view that predates the journal cannot be rebased until you re-read it",
                "view_revision": "every status and edit/revert answer reports it (status: view_revision and overlays.latest_editor); a named-view edit reports sync.phases_ms {master_open, fork, copy (part of fork: the engine's clone/copy time), base_upgrade, open, replay, total}, all whole milliseconds",
                "concurrency": "shared view: expect_revision is mandatory and stale edits conflict unless their subjects are untouched. Named views: per-agent isolation (one agent per view name); they are not merged back. Per-agent views by default is deferred until publish/merge exists",
                "struct": "path, size, fields=[{offset, type, name, length?}]", "signature": "prototype",
                "variable": "variable, type, name?", "apply": "type", "rename": "function name", "label": "name at a mapped address (including data)", "comment": "comment",
                "function_create/function_body": "expect=exact entry bytes, ranges=[{start,end}] numeric inclusive VAs; optional name",
                "function_delete": "expect=exact entry bytes; explicit entry VA",
                "batch": "edits=[{address,options}] OR file=JSON array path, 1..200 nonbatch children, atomic; source inherited if absent",
                "import_types": "corpus=absolute JSONL path (docs/type-corpus.md), category?; runs as a job; revertible in one step",
                "import_archive": "archive=absolute .gdt path; source required; paths=[exact type paths] optional. Whole archive requires matching data organization; selected types use strict recursive layout checks. Runs as a job and reverts as one edit",
                "revert": "ids=[overlay ids]: one step; the working copy is rebuilt from the master",
            },
            "vtables": "address = a function: the tables of code pointers that hold it, and its slot",
            "vcalls": {"offset": "slot byte offset (0xc0)", "vtable": "optional: names the implementation and its direct callers", "receiver_from/receiver_type/receiver_global": "optional: verify each site's receiver on p-code"},
            "writes": {"offset": "field offset", "receiver_type": "optional struct name to verify the store's base", "coverage": "direct [reg+offset] stores; the answer lists what it does not cover"},
            "orphans": {"referenced_only": "optional bool: only runs something refers to", "use": "decoded code no function contains, with references to each run's start: evidence for type_edit function_create"},
            "diff": {"against": "the other build's target (the source)", "against_view": "optional source annotation view; shared by default", "view": "optional destination annotation view; shared by default", "checks": "optional source prologue table; destination candidates require independent review, not ready-to-install checks; runs as a job"},
            "export": {"mode": "decompile/functions/types", "limit": "maximum records, default 100000", "contains": "optional function/type filter", "regex": "optional name/path regex", "start/end": "optional inclusive function VA range", "out": "optional absolute .jsonl output path", "timeout_s": "per-query deadline 1..300", "resume": "existing export job id; source/options identity must match"},
        },
        "type_persistence": "Edits are full-build-hash-bound overlays replayed only in worker memory. The canonical project is not saved or mutated.",
        "flow_limits": "Recovered high-pcode dependencies and direct-call bindings are evidence, not proof of runtime reachability, complete aliasing, or indirect targets.",
    }
